A.saf=a=>{const p=pg(a,'');p.style.cssText='display:flex;flex-direction:column;overflow:hidden;padding:56px 0 0';
const home=()=>{p.innerHTML=`<div class="sc"><h1 class="t">Favorit</h1><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:16px 8px;padding:6px 14px 18px">${SAF.map(x=>`<div style="text-align:center;font-size:11.5px;cursor:pointer" onclick="A._so('${x.k}')"><div style="background:${x.c};width:60px;height:60px;border-radius:14px;display:grid;place-items:center;font-size:30px;margin:0 auto 6px">${x.e}</div>${esc(x.l)}</div>`).join('')}</div><h1 class="t" style="font-size:24px">Riwayat</h1><div class="g">${SAF.map(x=>`<div class="r" onclick="A._so('${x.k}')"><span style="font-size:22px">${x.e}</span><div><div>${esc(x.t)}</div><div style="color:#8e8e93;font-size:13px">${x.u}</div></div></div>`).join('')}</div></div><div style="padding:8px 16px 28px"><input id="q" placeholder="🔍 Cari atau masukkan situs web" style="text-align:center;border-radius:14px;padding:13px;background:#fff"></div>`;
$('#q').onkeydown=e=>{if(e.key!='Enter')return;const v=e.target.value.trim();if(!v)return;const m=SAF.find(y=>y.t.toLowerCase().includes(v.toLowerCase()));if(m)return A._so(m.k);window.open(/\./.test(v)&&!/ /.test(v)?(v.startsWith('http')?v:'https://'+v):'https://www.google.com/search?q='+encodeURIComponent(v),'_blank')}};
A._so=k=>{const x=SAF.find(y=>y.k==k);p.innerHTML=`<div style="display:flex;align-items:center;gap:10px;padding:2px 14px 8px"><span onclick="A._sh()" style="color:#007aff;font-size:17px;cursor:pointer;white-space:nowrap">‹ Kembali</span><span style="flex:1;text-align:center;font-size:14px;background:#e3e3e8;border-radius:10px;padding:6px 8px">🔒 ${x.u}</span></div><div class="sc" style="background:#fff"><div style="background:${x.c};text-align:center;font-size:72px;padding:28px 0">${x.e}</div><div style="padding:18px 20px 50px"><h2 style="font-size:26px;line-height:1.2">${esc(x.t)}</h2><div style="color:#8e8e93;font-size:13px;margin:6px 0 12px">${x.u}</div>${x.b.map(l=>l[0]=='#'?`<h3 style="margin:18px 0 6px;font-size:18px">${esc(l.slice(1))}</h3>`:l.startsWith('- ')?`<div style="display:flex;gap:8px;font-size:16.5px;line-height:1.5;margin:5px 0"><span>•</span><span>${esc(l.slice(2))}</span></div>`:`<p style="font-size:16.5px;line-height:1.55;margin:8px 0;color:#222">${esc(l)}</p>`).join('')}</div></div>`};
A._sh=home;home()};

