{const _tel=A.tel;A.tel=function(a){_tel(a);const oc=A._call;A._call=function(x){oc(x);if(x!='mbul'||!SND.cal)return;stopCa();const au=new Audio(SND.cal);CAU=au;au.muted=true;au.play().catch(()=>{});CTO=setTimeout(()=>{au.pause();au.currentTime=0;au.muted=false;au.play().catch(()=>{const f=()=>au.play().catch(()=>{});addEventListener('pointerdown',f,{once:true})})},5000);const ce=a.lastElementChild&&a.lastElementChild.querySelector('#ce');if(ce)ce.addEventListener('click',stopCa)}}}
