let K=1;
function fit(){const vv=window.visualViewport,z=vv&&Math.abs(vv.scale-1)>.01,w=(vv&&!z&&vv.width)||innerWidth,h=(vv&&!z&&vv.height)||innerHeight,m=w<=600||(matchMedia('(pointer:coarse)').matches&&w<=1100),st=$('#stage');document.body.classList.toggle('mob',m);
if(m){K=w/390;const H=Math.round(h/K);document.documentElement.style.setProperty('--H',H+'px');st.style.transform=`scale(${K})`}
else{K=Math.min(h/880,w/430,1.3);document.documentElement.style.setProperty('--H','844px');st.style.transform=`translate(-50%,-50%) scale(${K})`}}
addEventListener('resize',fit);addEventListener('orientationchange',fit);if(window.visualViewport)visualViewport.addEventListener('resize',fit);if(!/iPhone|iPad|Macintosh/.test(navigator.userAgent))document.body.classList.add('na');fit();setWall(0);renderNt();
